// Mazher's Production-Grade Automated Test
test('Traveller completes payment with verified webhook confirmation', async ({ page }) => {
  // 1. Semantic, accessible locators
  await page.goto('/checkout');
  const submitBtn = page.getByRole('button', { name: /Complete Payment/i });

  // 2. Intercept asynchronous gateway callback
  const callbackPromise = page.waitForResponse(resp => 
    resp.url().includes('/api/payment/callback') && resp.status() === 200
  );

  // 3. User interaction
  await submitBtn.click();

  // 4. Assert non-flaky deterministic network response
  const callbackResponse = await callbackPromise;
  const responseJson = await callbackResponse.json();
  expect(responseJson.reconciled).toBe(true);

  // 5. Accessible confirmation announcement
  const statusAnnouncer = page.getByRole('status');
  await expect(statusAnnouncer).toContainText(/Payment Approved/i);
});
